/*
 * Build Automation Gateway request envelope for listDueNextActions.
 * - organizationId, connectionId, serviceId are bound server-side; body is a claim, never trusted alone.
 * - workflowId, workflowRevision, n8nExecutionId are computed inside the n8n host; we read them from $workflow and $execution.
 * - idempotencyKey is stable for the same wall-clock window so retries dedupe at the gateway.
 * - correlationId rides the whole flow; it is tracking only (digest excludes it on purpose).
 */
const slug = (s) => String(s || '').replace(/[^A-Za-z0-9._:-]/g, '').slice(0, 128);
const idem = 'sla-' + (new Date()).toISOString().slice(0, 16).replace(/[-:T]/g, '');
const envelope = {
  schemaVersion: '1',
  commandId: 'cmd-' + idem,
  commandName: 'listDueNextActions',
  idempotencyKey: idem,
  correlationId: 'corr-' + idem + '-' + Math.random().toString(36).slice(2, 10),
  organizationId: $env.HRP_AUTOMATION_ORG_ID,
  source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
  actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
  occurredAt: new Date().toISOString(),
  automationSource: {
    kind: 'N8N_AUTOMATION',
    workflowId: slug($workflow.id),
    workflowRevision: 1,
    n8nExecutionId: slug($execution.id),
    workflowLabel: 'sla-reminder-crm'
  },
  operation: {
    op: 'listDueNextActions',
    payload: {
      schemaVersion: '1',
      statusFilter: 'OVERDUE_ONLY',
      pageSize: 50
    }
  }
};
const rawBody = JSON.stringify(envelope);
return [
  {
    json: {
      envelope: envelope,
      rawBody: rawBody,
      credentialId: 'CRM_AUTOMATION_HMAC'
    }
  }
];

/*
 * Group reminder items by assignedToRedacted and acknowledge each batch via the gateway.
 * Acknowledgement is AUDIT-ONLY; it does NOT mutate NextAction status (Plan N8N/1.1 ranh giới).
 * If status != 'APPLIED' we surface the redacted error code; we never log the response body verbatim.
 */
const items = ($input.first().json && $input.first().json.data && $input.first().json.data.items) || [];
const acks = [];
const owners = new Set(items.map((it) => it.assignedToRedacted));
for (const owner of owners) {
  acks.push({
    json: {
      envelope: {
        schemaVersion: '1',
        commandId: 'cmd-ack-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
        commandName: 'acknowledgeReminder',
        idempotencyKey: 'ack-' + owner + '-' + new Date().toISOString().slice(0, 16).replace(/[-:T]/g, ''),
        correlationId: $input.first().json.envelope ? $input.first().json.envelope.correlationId : 'corr-' + Date.now(),
        organizationId: $env.HRP_AUTOMATION_ORG_ID,
        source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
        actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
        automationSource: {
          kind: 'N8N_AUTOMATION',
          workflowId: ($input.first().json.envelope && $input.first().json.envelope.automationSource && $input.first().json.envelope.automationSource.workflowId) || 'sla-reminder',
          workflowRevision: 1,
          n8nExecutionId: ($input.first().json.envelope && $input.first().json.envelope.automationSource && $input.first().json.envelope.automationSource.n8nExecutionId) || 'exec-' + Date.now(),
          workflowLabel: 'sla-reminder-crm'
        },
        operation: {
          op: 'acknowledgeReminder',
          payload: {
            schemaVersion: '1',
            nextActionId: 'batch-' + owner,
            notificationOutcome: 'SENT',
            reminderRevisionId: 'rev-' + new Date().toISOString().slice(0, 10),
            channel: 'DASHBOARD_ONLY'
          }
        }
      }
    }
  });
}
return acks;
